import base64
import json
import os
from typing import Any, Dict, Optional

from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient


STANDARD_SCHEMA = {
    "vendor_name": None,
    "invoice_number": None,
    "invoice_date": None,
    "due_date": None,
    "currency": None,
    "subtotal": None,
    "tax": None,
    "total": None,
    "payment_terms": None,
    "po_number": None,
    "bill_to": {
        "name": None,
        "address": None,
    },
    "ship_to": {
        "name": None,
        "address": None,
    },
    "line_items": [],
    "raw_fields": {},
}


def _to_float(value: Any) -> Optional[float]:
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    text = str(value).strip()
    if not text:
        return None
    cleaned = "".join(ch for ch in text if ch.isdigit() or ch in ".-,")
    cleaned = cleaned.replace(",", "")
    try:
        return float(cleaned)
    except ValueError:
        return None


def _to_str(value: Any) -> Optional[str]:
    if value is None:
        return None
    if hasattr(value, "value"):
        value = value.value
    text = str(value).strip()
    return text or None


def _extract_field(analyzed_doc: Any, field_name: str) -> Any:
    fields = getattr(analyzed_doc, "fields", None) or {}
    field = fields.get(field_name)
    if field is None:
        return None
    if hasattr(field, "value"):
        return field.value
    return field


def _extract_address(address_field: Any) -> Optional[str]:
    if not address_field:
        return None
    if isinstance(address_field, str):
        return address_field.strip() or None
    parts = []
    for attr in (
        "street_address",
        "city",
        "state",
        "postal_code",
        "country_region",
    ):
        val = getattr(address_field, attr, None)
        if val:
            parts.append(str(val).strip())
    if parts:
        return ", ".join(parts)
    return _to_str(address_field)


def normalize_expense_fields(
    document_bytes: bytes,
    content_type: str = "application/pdf",
    model_id: str = "prebuilt-invoice",
    endpoint: Optional[str] = None,
    api_key: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Normalize extracted expense fields into a standard JSON schema using
    Azure Document Intelligence prebuilt invoice.

    Args:
        document_bytes: Raw bytes of the document/image/PDF.
        content_type: MIME type for the input document.
        model_id: Azure prebuilt model ID, defaults to "prebuilt-invoice".
        endpoint: Azure Document Intelligence endpoint. Falls back to env var.
        api_key: Azure Document Intelligence key. Falls back to env var.

    Returns:
        Dict matching the standard schema.
    """
    endpoint = endpoint or os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    api_key = api_key or os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint or not api_key:
        raise ValueError(
            "Missing Azure Document Intelligence credentials. "
            "Set AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY."
        )

    client = DocumentIntelligenceClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(api_key),
    )

    poller = client.begin_analyze_document(
        model_id=model_id,
        analyze_request=document_bytes,
        content_type=content_type,
    )
    result = poller.result()

    documents = getattr(result, "documents", None) or []
    if not documents:
        return STANDARD_SCHEMA.copy()

    doc = documents[0]
    out = json.loads(json.dumps(STANDARD_SCHEMA))

    out["vendor_name"] = _to_str(_extract_field(doc, "VendorName"))
    out["invoice_number"] = _to_str(_extract_field(doc, "InvoiceId"))
    out["invoice_date"] = _to_str(_extract_field(doc, "InvoiceDate"))
    out["due_date"] = _to_str(_extract_field(doc, "DueDate"))
    out["currency"] = _to_str(_extract_field(doc, "InvoiceCurrency"))
    out["subtotal"] = _to_float(_extract_field(doc, "SubTotal"))
    out["tax"] = _to_float(_extract_field(doc, "TotalTax"))
    out["total"] = _to_float(_extract_field(doc, "InvoiceTotal"))
    out["payment_terms"] = _to_str(_extract_field(doc, "PaymentTerm"))
    out["po_number"] = _to_str(_extract_field(doc, "PurchaseOrder"))

    bill_to = _extract_field(doc, "BillingAddress")
    if bill_to:
        out["bill_to"]["name"] = _to_str(getattr(bill_to, "recipient", None))
        out["bill_to"]["address"] = _extract_address(bill_to)

    ship_to = _extract_field(doc, "ShippingAddress")
    if ship_to:
        out["ship_to"]["name"] = _to_str(getattr(ship_to, "recipient", None))
        out["ship_to"]["address"] = _extract_address(ship_to)

    line_items = []
    items = _extract_field(doc, "Items")
    if items and isinstance(items, list):
        for item in items:
            name = _extract_field(item, "Description")
            qty = _extract_field(item, "Quantity")
            unit_price = _extract_field(item, "UnitPrice")
            amount = _extract_field(item, "Amount")
            line_items.append(
                {
                    "description": _to_str(name),
                    "quantity": _to_float(qty),
                    "unit_price": _to_float(unit_price),
                    "amount": _to_float(amount),
                    "raw_fields": {
                        k: _to_str(v.value if hasattr(v, "value") else v)
                        for k, v in getattr(item, "fields", {}).items()
                    },
                }
            )
    out["line_items"] = line_items

    out["raw_fields"] = {
        k: _to_str(v.value if hasattr(v, "value") else v)
        for k, v in getattr(doc, "fields", {}).items()
    }

    return out


def normalize_expense_fields_from_base64(
    document_base64: str,
    content_type: str = "application/pdf",
    model_id: str = "prebuilt-invoice",
    endpoint: Optional[str] = None,
    api_key: Optional[str] = None,
) -> Dict[str, Any]:
    document_bytes = base64.b64decode(document_base64)
    return normalize_expense_fields(
        document_bytes=document_bytes,
        content_type=content_type,
        model_id=model_id,
        endpoint=endpoint,
        api_key=api_key,
    )
